import base64
import json
import os
from typing import Any, Dict, Optional

import boto3


def _read_input_document(document: Any) -> bytes:
    if document is None:
        raise ValueError("document is required")

    if isinstance(document, (bytes, bytearray)):
        return bytes(document)

    if isinstance(document, str):
        if os.path.exists(document):
            with open(document, "rb") as f:
                return f.read()
        return base64.b64decode(document)

    if hasattr(document, "read"):
        data = document.read()
        if isinstance(data, str):
            data = data.encode("utf-8")
        return bytes(data)

    raise TypeError("document must be bytes, file path, base64 string, or file-like object")


def _money_to_dict(money_obj: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    if not money_obj:
        return None
    amount = money_obj.get("Amount")
    currency = money_obj.get("CurrencyCode")
    if amount is None and currency is None:
        return None
    return {"amount": amount, "currency": currency}


def _normalize_expense_item(item: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "description": item.get("Description", {}).get("Text") if isinstance(item.get("Description"), dict) else item.get("Description"),
        "quantity": item.get("Quantity", {}).get("Value") if isinstance(item.get("Quantity"), dict) else item.get("Quantity"),
        "unit_price": _money_to_dict(item.get("Price")) if isinstance(item.get("Price"), dict) else None,
        "amount": _money_to_dict(item.get("Amount")) if isinstance(item.get("Amount"), dict) else None,
        "category": item.get("Category"),
        "subcategories": item.get("SubCategories", []),
    }


def _normalize_field(field: Dict[str, Any]) -> Any:
    if not field:
        return None

    field_type = field.get("Type", {}).get("Text") if isinstance(field.get("Type"), dict) else field.get("Type")
    value = field.get("ValueDetection", {}).get("Text") if isinstance(field.get("ValueDetection"), dict) else field.get("Value")

    if field_type in {"INVOICE_RECEIPT_DATE", "INVOICE_RECEIPT_TOTAL", "TOTAL"}:
        return value
    return value


def normalize_expense_fields(document: Any, region_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Normalize expense fields into a standard JSON schema using Amazon Textract AnalyzeExpense.

    Input:
        document: bytes, base64 string, file path, or file-like object
        region_name: optional AWS region (defaults to AWS config or us-east-1)

    Output schema:
    {
        "vendor_name": str|None,
        "vendor_address": str|None,
        "invoice_number": str|None,
        "invoice_date": str|None,
        "due_date": str|None,
        "currency": str|None,
        "subtotal": {"amount": ..., "currency": ...}|None,
        "tax": {"amount": ..., "currency": ...}|None,
        "tip": {"amount": ..., "currency": ...}|None,
        "total": {"amount": ..., "currency": ...}|None,
        "line_items": [
            {"description": ..., "quantity": ..., "unit_price": ..., "amount": ..., "category": ..., "subcategories": ...}
        ],
        "raw": {...}
    }
    """
    image_bytes = _read_input_document(document)

    client = boto3.client("textract", region_name=region_name)

    response = client.analyze_expense(Document={"Bytes": image_bytes})

    normalized: Dict[str, Any] = {
        "vendor_name": None,
        "vendor_address": None,
        "invoice_number": None,
        "invoice_date": None,
        "due_date": None,
        "currency": None,
        "subtotal": None,
        "tax": None,
        "tip": None,
        "total": None,
        "line_items": [],
        "raw": response,
    }

    expense_documents = response.get("ExpenseDocuments", []) or []
    if not expense_documents:
        return normalized

    doc = expense_documents[0]

    for field in doc.get("SummaryFields", []) or []:
        ftype = field.get("Type", {}).get("Text") if isinstance(field.get("Type"), dict) else field.get("Type")
        value = field.get("ValueDetection", {}).get("Text") if isinstance(field.get("ValueDetection"), dict) else field.get("ValueDetection")

        if ftype == "VENDOR_NAME":
            normalized["vendor_name"] = value
        elif ftype in {"VENDOR_ADDRESS", "ADDRESS"}:
            normalized["vendor_address"] = value
        elif ftype in {"INVOICE_RECEIPT_ID", "INVOICE_NUMBER"}:
            normalized["invoice_number"] = value
        elif ftype in {"INVOICE_RECEIPT_DATE", "TRANSACTION_DATE"}:
            normalized["invoice_date"] = value
        elif ftype == "DUE_DATE":
            normalized["due_date"] = value
        elif ftype in {"SUBTOTAL", "SUB_TOTAL"}:
            normalized["subtotal"] = _money_to_dict(field.get("ValueDetection", {}))
        elif ftype == "TAX":
            normalized["tax"] = _money_to_dict(field.get("ValueDetection", {}))
        elif ftype in {"TIP", "GRATUITY"}:
            normalized["tip"] = _money_to_dict(field.get("ValueDetection", {}))
        elif ftype in {"TOTAL", "AMOUNT_DUE"}:
            normalized["total"] = _money_to_dict(field.get("ValueDetection", {}))
        elif ftype == "CURRENCY":
            normalized["currency"] = value

    items = doc.get("LineItemGroups", []) or []
    for group in items:
        for item in group.get("LineItems", []) or []:
            normalized["line_items"].append(_normalize_expense_item(item))

    if normalized["currency"] is None:
        for money_field in (normalized["subtotal"], normalized["tax"], normalized["tip"], normalized["total"]):
            if money_field and money_field.get("currency"):
                normalized["currency"] = money_field["currency"]
                break

    return normalized


def extract_expense_json(document: Any, region_name: Optional[str] = None) -> str:
    return json.dumps(normalize_expense_fields(document, region_name=region_name), ensure_ascii=False, default=str)
